  phoneX = 380,
  phoneY = 70,
  startDelay = 0.6,
  hold = 1.6,
}) => {
  const t = useCurrentFrame() / FPS;

  // 目标点移动时，折线与标签随之整体平移（保持折线角度与标签贴线关系）
