          );
        })}
      </svg>
      <div>
        {callouts.map((c, i) => {
          const t0 = startDelay + i * FIXED.stagger;
          const tOut = outAt + i * 0.15;
          const tLabel = t0 + FIXED.dotIn + FIXED.lineDraw;

          // 3) 标签：clip-path 从线端方向展开，文字滞后 0.1s 淡入
          const shown = t < tOut
            ? tw(t, tLabel, FIXED.labelIn, power3Out)
