function parseMessages(dsl: string): Msg[] {
  return dsl
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => {
      const parts = l.split("|");
      const from = parts[0].trim() === "me" ? "me" : "them";
      if (parts.length <= 2) return { from, text: (parts[1] ?? "").trim() } as Msg;
      return {
        from,
        text: parts.slice(1, -1).join("|").trim(),
        react: parts[parts.length - 1].trim() || undefined,
      } as Msg;
    });
}

