function parseLines(dsl: string): LineSpec[] {
  return dsl
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => {
      const parts = l.split("|");
      if (parts.length < 3) return { k: "res", d: 0.3, text: parts[parts.length - 1] ?? "" };
      const dNum = Number(parts[1].trim());
      return {
        k: parts[0].trim(),
        d: Number.isFinite(dNum) ? dNum : 0.3,
        text: parts.slice(2).join("|"),
      };
    });
}

