              clipPath: `inset(0 ${restClip}% 0 0)`, transform: `translateX(${restX}px)`,
            }}
          >
            {restText}
          </span>
        </div>
        <div
          style={{
            fontSize: restSize, fontWeight: 600, lineHeight: 1.2,
