export default function CrashZoomPunch({ src, target = DEMO_TARGET, label = "自动续费", sub = "下次扣款 2026-10-05 · ¥ 199 / 月" }: Props) {
  const t = useCurrentFrame() / FPS;

  // 目标中心钉死：推进与回收共用同一 (px, py)
  const px = target.x + target.w / 2, py = target.y + target.h / 2;
  const a = camTo(CONFIG.zoom, px, py), b = camTo(CONFIG.settle, px, py);

  // 相机：全景 → 6 帧急推到过冲峰值 → 5 帧回收落定 → 钉死
  const pIn = tw(t, CONFIG.hold, CONFIG.punch, power3In);
  const pSettle = tw(t, CONFIG.hold + CONFIG.punch, CONFIG.settleDur, power2Out);
  const cam = {
    scale: lerp(lerp(1, a.scale, pIn), b.scale, pSettle),
    x: lerp(lerp(0, a.x, pIn), b.x, pSettle),
    y: lerp(lerp(0, a.y, pIn), b.y, pSettle),
  };
  // 运动模糊只包急推段：0.12s 升到峰值，再 0.15s 落回 0
  const blur = CONFIG.blur * (tw(t, CONFIG.hold, CONFIG.punch * 0.6, power2In) - tw(t, CONFIG.hold + CONFIG.punch * 0.6, 0.15, power1Out));
  const exitK = 1 - tw(t, CONFIG.exitAt, CONFIG.end - CONFIG.exitAt, power2In);

  return (
    <AbsoluteFill style={{ background: "#f5f5f7", color: "#1d1d1f", overflow: "hidden", fontFamily: '"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif' }}>
      <style>{CSS}</style>
      <div className="czp-cam" style={{ opacity: exitK, transform: `translate(${cam.x}px, ${cam.y}px) scale(${cam.scale})`, filter: `blur(${Math.max(0, blur).toFixed(2)}px)` }}>
        <div className="czp-shot">
          {src ? (
            <Img src={src} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
          ) : (
            <>
              <div className="czp-hd">订阅与账单</div>
              <div className="czp-li"><span className="czp-ic"><i className="czp-ico" /><span className="czp-g" style={{ width: 96 }} /></span><span className="czp-k"><span className="czp-g" style={{ width: 150 }} /></span><span className="czp-sp" /><span className="czp-sw" /></div>
              <div className="czp-li"><span className="czp-ic"><i className="czp-ico" /><span className="czp-g" style={{ width: 70 }} /></span><span className="czp-k"><span className="czp-g" style={{ width: 190 }} /></span><span className="czp-sp" /><span className="czp-sw on" /></div>
              <div className="czp-li czp-tg"><span className="czp-ic"><i className="czp-ico" /><span className="czp-g" style={{ width: 84 }} /></span><span className="czp-k">{label}<small>{sub}</small></span><span className="czp-sp" /><span className="czp-sw on" /></div>
              <div className="czp-li"><span className="czp-ic"><i className="czp-ico" /><span className="czp-g" style={{ width: 110 }} /></span><span className="czp-k"><span className="czp-g" style={{ width: 120 }} /></span><span className="czp-sp" /><span className="czp-g czp-g2" /></div>
              <div className="czp-li"><span className="czp-ic"><i className="czp-ico" /><span className="czp-g" style={{ width: 60 }} /></span><span className="czp-k"><span className="czp-g" style={{ width: 170 }} /></span><span className="czp-sp" /><span className="czp-sw" /></div>
            </>
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
}

