function parseRows(dsl: string): Row[] {
  return dsl
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => {
      const parts = l.split("|");
      return {
        b: (parts[0] ?? "").trim(),
        s: (parts[1] ?? "").trim(),
        on: (parts[2] ?? "").trim() === "on",
      };
    });
}

