type Props = {
  /** 文档标题（mock 文档顶部；传 docSrc 时不显示） */
  docTitle?: string;
  /** 三条结论（药丸文案，按口播顺序） */
  pills?: string[];
  /** 每条结论下的一行说明（与 pills 同序） */
  notes?: string[];
  /** 提示行 */
  hint?: string;
  /** 真文档长截图（cover 铺进文档卡，随内容一起慢滚）；不传 = 灰条 mock */
  docSrc?: string;
  /** 药丸圆点颜色（唯一强调色） */
  accent?: string;
};

component.$expression:
({
  docTitle = "2026 中国短视频创作者调研报告",
  pills = DEFAULT_PILLS,
  notes = DEFAULT_NOTES,
