  docSrc = "",
  accent = "#0066cc",
}) => (
  <T
    docTitle={docTitle}
    pills={lines(pills)}
    notes={lines(notes)}
    hint={hint}
    docSrc={docSrc || undefined}
    accent={accent}
  />
)

