export default function InfoTermCard({ hostSrc }: { hostSrc?: string }) {
  const t = useCurrentFrame() / FPS;

  // —— x：滑入 → 过冲回稳 → 停留后原路滑出 ——
  const outAt = CONFIG.slideIn + 0.16 + CONFIG.holdBeforeOut;   // 3.71
  const x = t < CONFIG.slideIn
    ? lerp(CONFIG.offX, -CONFIG.overshootPx, tw(t, 0, CONFIG.slideIn, power3Out))
    : t < outAt
      ? lerp(-CONFIG.overshootPx, 0, tw(t, CONFIG.slideIn, 0.16, power2Out))
      : lerp(0, CONFIG.offX, tw(t, outAt, CONFIG.slideOut, power2In));

  // —— 落位后：y 正弦浮动营造"悬浮"，图标跟着微转（yoyo repeat 3 = 共 4 个半程）——
  const floatStart = CONFIG.slideIn + 0.16 + 0.05;   // 0.56
  const fp = sineInOut(yoyoP(t, floatStart, CONFIG.floatPeriod / 2, 4));
  const y = CONFIG.floatPx * fp;
  const iconRot = CONFIG.iconTilt * fp;

  return (
    <AbsoluteFill style={{
      background: "#ffffff", color: "#1d1d1f", overflow: "hidden",
      fontFamily: '"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif',
    }}>
      <style>{CSS}</style>
      <Host src={hostSrc} />
      <div className="term-card" style={{ transform: `translate(${x}px, ${y}px)` }}>
        <div className="icon" style={{ transform: `rotate(${iconRot}deg)` }}>¥</div>
        <div>
          <div className="term">量化宽松<small>QE</small></div>
          <div className="desc">央行"印钱"买入国债等资产，把流动性压进市场，刺激经济。</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

component.$expression:
({
  term = "量化宽松",
  termSmall = "QE",
  desc = '央行"印钱"买入国债等资产，把流动性压进市场，刺激经济。',
  iconChar = "¥",
  inkColor = "#1d1d1f",
  cardBg = "#ffffff",
  termSize = 20,
  descSize = 14,
  cardW = 330,
  posRight = 56,
  posY = 194.4,
  hold = 3.2,
  offX = 480,
}) => {
  const t = useCurrentFrame() / FPS;

  // —— x：滑入 → 过冲回稳 → 停留后原路滑出 ——
  const outAt = FIXED.slideIn + 0.16 + hold;   // 默认 3.71
  const x = t < FIXED.slideIn
    ? lerp(offX, -FIXED.overshootPx, tw(t, 0, FIXED.slideIn, power3Out))
    : t < outAt
      ? lerp(-FIXED.overshootPx, 0, tw(t, FIXED.slideIn, 0.16, power2Out))
      : lerp(0, offX, tw(t, outAt, FIXED.slideOut, power2In));

  // —— 落位后：y 正弦浮动营造"悬浮"，图标跟着微转 ——
  // 原卡 repeat 3 = 共 4 个半程；hold 拉长时按需补趟数（默认值下 plays 恰为 4，逐像素一致）
  const floatStart = FIXED.slideIn + 0.16 + 0.05;   // 0.56
  const plays = Math.max(4, Math.ceil((outAt + FIXED.slideOut - floatStart) / (FIXED.floatPeriod / 2)));
  const fp = sineInOut(yoyoP(t, floatStart, FIXED.floatPeriod / 2, plays));
  const y = FIXED.floatPx * fp;
  const iconRot = FIXED.iconTilt * fp;

  return (
    <AbsoluteFill style={{ background: "#ffffff", color: "#1d1d1f", overflow: "hidden", fontFamily: FONT_STACK }}>
