function parseShots(dsl: string): Shot[] {
  return dsl
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => {
      const p = l.split("|").map((s) => s.trim());
      return {
        kind: p[0] || "browser",
        x: Number(p[1]) || 0,
        y: Number(p[2]) || 0,
        w: Number(p[3]) || 200,
        h: Number(p[4]) || 140,
        rot: Number(p[5]) || 0,
      };
    });
}

