    }}>
      <style>{CSS}</style>
      {/* 方向模糊滤镜：stdDeviation="σ 0" = 只糊横向，才读作速度而不是失焦。
          filter 区域必须放宽（x/width），否则拖影会被裁出硬边；sRGB 防白底上发灰的脏边 */}
      <svg style={{ position: "absolute", width: 0, height: 0, overflow: "hidden" }} aria-hidden>
        <defs>
