          className="mbsi-shot"
          style={{
            width: 230, height: 150, left: bPosX, top: bPosY, zIndex: 3,
            transform: `translateX(${b.x}px)`, filter: filterOf(b.sigma, "mbsi-b"),
          }}
        >
