function parseCards(dsl: string): NewsCard[] {
  return dsl
    .split("\n")
    .filter((l) => l.trim() !== "")
    .map((l) => {
      const p = l.split("|").map((s) => s.trim());
      return {
        paper: p[0] || "",
        date: p[1] || "",
        headline: p[2] || "",
        bars: Number(p[3]) || 0,
        x: Number(p[4]) || 0,
        y: Number(p[5]) || 0,
        w: Number(p[6]) || 330,
        tilt: Number(p[7]) || 0,
      };
    });
}

