            <span className="sp-slab-bg" style={{ transform: `scaleX(${bgScaleX})` }} />
            <span className="sp-l2-t" style={{ opacity: l2Opacity, transform: `scale(${l2Scale})` }}>
              关键点
            </span>
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
}

