export default function StepTimelineVertical({ hostSrc }: { hostSrc?: string }) {
  const t = useCurrentFrame() / FPS;

  // ① 竖线从上往下画出
  const lineP = tw(t, CONFIG.lead, CONFIG.lineDur, power1InOut);

  // ② 线经过节点 → 该节点弹出 → 2 帧后右侧两行字跟上
  const nodeAts = STEPS.map((s) =>
    CONFIG.lead + CONFIG.lineDur * invPower1InOut(s.at / WRAP_H));
  const lastEnd = Math.max(
    CONFIG.lead + CONFIG.lineDur,
    ...nodeAts.map((at) => at + CONFIG.textLag + CONFIG.textDur));

  // ③ 全部到位后，当前节点（第一个）升级为强调色空心环
  const ringAt = lastEnd + CONFIG.ringDelay;
  const ringP = tw(t, ringAt, CONFIG.ringDur, power3Out);

  return (
    <AbsoluteFill style={{
      background: "#ffffff", color: "#1d1d1f", overflow: "hidden",
      fontFamily: '"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif',
    }}>
      <style>{CSS}</style>
      <div className="host-col"><Host src={hostSrc} /></div>

      <div className="tl-wrap">
        <div className="tl-line" style={{ transform: `scaleY(${lineP})` }} />
        {STEPS.map((s, i) => {
          const at = nodeAts[i];
          const popScale = tw(t, at, CONFIG.nodePop, backOut(1.6));
          // 节点 0 升级：pop 早已结束（scale 1）→ ring 阶段 1→1.25
          const scale = i === 0 && t >= ringAt ? lerp(1, CONFIG.ringScale, ringP) : popScale;
          const borderW = i === 0 ? CONFIG.ringWidth * ringP : 0;
          const bg = i === 0
            ? lerpColor([29, 29, 31], [255, 255, 255], ringP)
            : "#1d1d1f";
          const textP = tw(t, at + CONFIG.textLag, CONFIG.textDur, power3Out);
          return (
            <React.Fragment key={i}>
              <div className="tl-node" style={{
                top: s.at - 7,
                transform: `scale(${scale})`,
                borderWidth: borderW,
                backgroundColor: bg,
              }} />
              <div style={{
                opacity: textP,
                transform: `translateX(${lerp(-CONFIG.textShift, 0, textP)}px)`,
              }}>
                <div className="tl-text" style={{ top: s.at - 26 }}>
                  <div className="tl-kicker">{s.kicker}</div>
                  <div className="tl-title">{s.title}</div>
                </div>
              </div>
            </React.Fragment>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

component.$expression:
({
  stepsDsl = DEFAULT_STEPS,
  accentColor = "#e0452c",
  titleSize = 25,
  posX = 132,
  posY = 118,
  rowGap = 110,
  lead = 0.4,
}) => {
  const t = useCurrentFrame() / FPS;
  const steps = parseSteps(stepsDsl);

  // 几何随条数走：线全长 = 首尾各留 22 + 节点等距 rowGap（默认 3 条 ⇒ 264，与原卡一致）
  const wrapH = FIXED.nodeY0 * 2 + rowGap * Math.max(0, steps.length - 1);
  const nodeY = (i: number) => FIXED.nodeY0 + rowGap * i;

  // ① 竖线从上往下画出
  const lineP = tw(t, lead, FIXED.lineDur, power1InOut);

  // ② 线经过节点 → 该节点弹出 → 2 帧后右侧两行字跟上
  const nodeAts = steps.map((_, i) =>
    lead + FIXED.lineDur * invPower1InOut(nodeY(i) / wrapH));
  const lastEnd = Math.max(
    lead + FIXED.lineDur,
    ...nodeAts.map((at) => at + FIXED.textLag + FIXED.textDur));

  // ③ 全部到位后，当前节点（第一个）升级为强调色空心环
  const ringAt = lastEnd + FIXED.ringDelay;
  const ringP = tw(t, ringAt, FIXED.ringDur, power3Out);

  return (
    <AbsoluteFill style={{ background: "#ffffff", color: "#1d1d1f", overflow: "hidden", fontFamily: FONT_STACK }}>
      <style>{CSS}</style>
      <div className="stv-host"><HostSilhouette /></div>

      <div className="stv-wrap" style={{ left: posX, top: posY, height: wrapH }}>
        <div className="stv-line" style={{ transform: `scaleY(${lineP})` }} />
        {steps.map((s, i) => {
          const at = nodeAts[i];
          const popScale = tw(t, at, FIXED.nodePop, backOut(1.6));
          // 节点 0 升级：pop 早已结束（scale 1）→ ring 阶段 1→1.25
          const scale = i === 0 && t >= ringAt ? lerp(1, FIXED.ringScale, ringP) : popScale;
          const borderW = i === 0 ? FIXED.ringWidth * ringP : 0;
          const bg = i === 0 ? mixHex("#1d1d1f", "#ffffff", ringP) : "#1d1d1f";
          const textP = tw(t, at + FIXED.textLag, FIXED.textDur, power3Out);
          return (
            <React.Fragment key={i}>
              <div className="stv-node" style={{
                top: nodeY(i) - 7,
                transform: `scale(${scale})`,
                borderWidth: borderW,
                borderColor: accentColor,   /* 当前节点升级成空心环时才长出来 */
                backgroundColor: bg,
              }} />
              <div style={{
                opacity: textP,
                transform: `translateX(${lerp(-FIXED.textShift, 0, textP)}px)`,
              }}>
                <div className="stv-text" style={{ top: nodeY(i) - 26 }}>
                  <div className="stv-kicker">{s.kicker}</div>
                  <div className="stv-title" style={{ fontSize: titleSize }}>{s.title}</div>
                </div>
              </div>
            </React.Fragment>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

