  } else {
    // hold 期：以末速继续漂 + rotateY 极缓回一点点（相机永不静止）
    const p = clamp01((t - t2) / Math.max(1e-6, holdDur));
    x = lerp(C.xTo, C.xTo + dir * holdRate * holdDur, p);
