}) => {
  const t = useCurrentFrame() / FPS;
  const { sched } = buildSchedule(parseLines(lines), lead, lineDelay, hover);
  const N = sched.length;

  // 行高/光标/窗高全部由字号推导（默认 21 ⇒ 行高 34、窗高 356，与模板逐像素一致）
  const lineHeight = Math.round(fontSize * 1.6);
