  let steps = 0;
  for (let i = FIXED.visibleLines; i < N; i++) if (t >= sched[i].start) steps++;
  const ty = -steps * lineHeight;

  const blinkOn = Math.floor(t * FIXED.cursorHz) % 2 === 0;

  return (
    <AbsoluteFill style={{
      background: "#ffffff", color: "#1d1d1f", overflow: "hidden", fontFamily: FONT_STACK,
