({
  tag = "全新版本 2.0",
  title = "把你的调研，变成一条能播的片子",
  desc = "从口播稿到成片，时间戳对齐、镜头分层、动效选型全部自动接管，导出即可发布。",
  featsDsl = DEFAULT_FEATS,
