              };
            } else {
              // 重音词：气质已由样式换掉（衬线斜体放大 / 强调色放大），
              // 运动只做"从基线下方上滑回落 + 轻放大淡入"，power3.out 收得干净
              const skew = item.emph === "serif" ? FIXED.obliqueDeg : 0;
